local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["f3064ca7d7baf46d"] = { "Il generale dei Piccatonante è morto!", "." },
  ["f30770a29a035b9b"] = { "Posso aiutarti?", "." },
  ["f307b115424e88c1"] = { "La foresta mi ha parlato della tua presenza, ma non del perché sei qui. Quindi parla, e illuminami.", "." },
  ["f3142bcd242ba0fe"] = { "Senti la potenza, {name}??? È l'ora del ROCK!", "." },
  ["f31a2ab2697a03fa"] = { "I figli di Sul proteggeranno il loro padrone. Risorgi ancora una volta, Sul'lithuz!", "." },
  ["f31ca8128d4d928d"] = { "Cerchi di allontanarmi dalla mia covata? Pagherai per la tua insolenza!", "." },
  ["f32d3fcad2bd3036"] = { "Le cose che ti insegnerei ti ridurrebbero il cervello in gelatina! Torna quando avrai imparato abbastanza!", "." },
  ["f33a63e8dfdb15b6"] = { "Non solo ho tutti i lingotti di mithril che mi servono, ma adesso anche tutte le raccolte dell'⟦Horde=Orda⟧ sono finite, mon. Pare che stiamo solo aspettando l'⟦Alliance=Alleanza⟧, e poi si va in guerra!", "." },
  ["f33aa9b86e049dfa"] = { "Non smetterei mai di lodare il tuo lavoro: è straordinario quello che sai fare con martello e incudine. Ora, non andare a dire in giro che ti ho suggerito di cercarti un goblin come maestro, ma è proprio quello che farò. Si chiama Brikk Keencraft e, per quanto ne so, gestisce una bottega giù alla ⟦Booty Bay=Baia del Bottino⟧.", "." },
  ["f340237288b241dc"] = { "Solo nella Natura troviamo la purezza.", "." },
  ["f347900e11b680f6"] = { "Devo andare. Il male si risveglia. Muori con onore, Omarion.", "." },
  ["f3562d70eb0ed868"] = { "Le bottiglie sono impolverate, ma il liquore va giù che è una meraviglia!", "." },
  ["f35f6830f95fea32"] = { "Continuo a non capire del tutto.", "." },
  ["f36189401f11ad95"] = { "Continua la tua storia, per favore.", "." },
  ["f367e0013779d24a"] = { "Fordring non vedrà mai suo figlio.", "." },
  ["f368e4e1b5a7a3df"] = { "Dazalar è famoso a Dolanaar per la sua abilità nella caccia. Perché non gli parli e vedi cosa può insegnarti?", "." },
  ["f370ee3391f58125"] = { "Sì, amico, io sono l'aiutante di Gadrin. Questo volontariato è il mio modo per arrivare in fondo alla scuola per santoni. Visto che tu hai aiutato lui, io aiuto te gratis. Cosa ti serve aggiustare?", "." },
  ["f3713dc093b71ec3"] = { "Dai la caccia a Deathclasp, {name}? Mi hai colpito. Solo questa settimana mi ha ucciso due uomini. Speriamo che tu abbia più fortuna di loro.", "." },
  ["f375c096f3e33762"] = { "Myolor, un tempo forgiavo armature e voglio impugnare di nuovo il martello! Insegnami la via del fabbro d'armature.", "." },
  ["f37ee302e85b452b"] = { "Ho perso la mia ⟦Band of Veiled Shadows=Vera delle Ombre Velate⟧. Puoi sostituirmela?", "." },
  ["f3809052cab95974"] = { "OH NO! Il re essere morto! Ehm... lunga vita al nuovo re! Sì!", "." },
  ["f381137821e86bb8"] = { "Che la lama ti purifichi, feccia!", "." },
  ["f38675f89ce52acb"] = { "Lok'tar, {class}! Abbiamo bisogno dei tuoi servigi nella ⟦Alterac Valley=Valle d'Alterac⟧. Vuoi che ti iscriva alle liste?", "." },
  ["f393caa05f9aec75"] = { "Vedo che il tuo guardaroba ha disperatamente bisogno di cure.", "." },
  ["f394115207907661"] = { "All'armi! Il Flagello è stato avvistato nella ⟦Cathedral of Light=Cattedrale della Luce⟧!", "." },
  ["f39c9bc09868c51e"] = { "Nel tumulto della Separazione, ⟦Ameth'Aran=Ameth'aran⟧ era in balia del terrore che attanagliava la terra. Le speranze di sopravvivere erano poche.", "." },
  ["f39da81e9db571e4"] = { "Sento campane nuziali nel tuo futuro.", "." },
  ["f39e9704e3e2a096"] = { "%s usa l'offerta di {name} in un rituale...", "." },
  ["f3a8a795ce9dad33"] = { "Aspetta! Ma che sto pensando! Abbiamo un lavoro da fare con questa roba.", "." },
  ["f3adb522cc558157"] = { "Ehilà, {class}, non lo sai? L'⟦Horde=Orda⟧ ha finito con tutte le raccolte. Stiamo solo ultimando i preparativi mentre aspettiamo che l'⟦Alliance=Alleanza⟧ finisca di raccogliere. Poi sarà ora di spedire tutto a ⟦Silithus=Silitus⟧ per la guerra.", "." },
  ["f3b2b7fe89458036"] = { "Quel giorno Windsor era particolarmente scorbutico, e credimi, per Windsor è un risultato monumentale. Continuava a ripetermi che \"c'era qualcosa che non andava\". Beh, non scherzava!\n\nEravamo nel bel mezzo del ⟦Blackrock Mountain=Massiccio Roccianera⟧ quando quegli animali schifosi ci attaccarono. Parlo degli orchi, naturalmente. Presta attenzione, eh? Si sentivano solo grugniti e il clangore dell'acciaio mentre ci piombavano addosso.", "." },
  ["f3b2d3b0045b3a44"] = { "Possiedo grandi poteri magici, e ho passato i miei giorni a studiare la mente e la memoria in rapporto all'apprendimento e alla conservazione delle abilità apprese. Starei ancora perfezionando i miei studi, se non fosse per le grandi voci che mi sono giunte nella notte, informandomi che i miei servigi erano richiesti. Resterò qui solo per breve tempo, offrendo gratuitamente la mia capacità di azzerare i tuoi talenti. Presto me ne andrò di nuovo, e dovrai ancora una volta tenerti le scelte che farai.", "." },
  ["f3b83033829912ce"] = { "Se i miei calcoli sono giusti, presto la ruota sarà obsoleta!", "." },
  ["f3b9bf15fcc82d64"] = { "Grazie ancora, {name}. Io e Rocknot andiamo proprio d'accordo!", "." },
  ["f3d465de6ab4b307"] = { "Sono buone lame quelle che fai, {name}. Tagliano una pietra e restano abbastanza affilate da squarciare una gola. Ne ho viste di migliori, però: le fa un orco di nome Kelgrum Bloodaxe. Va' da lui e impara tutto ciò che può insegnarti.", "." },
  ["f3d95346a38763af"] = { "Salve, <buon/buona> <signore/signora>. Siediti, e mangia qualcosa se hai fame. Non badare al mio ricamo: ti sto ascoltando...", "." },
  ["f3e4fe170d9e7496"] = { "Ce l'hai fatta?! Mi sorprende che Kinelory non ti abbia rallentato più di così. Kin, ecco i tuoi calzini. Dammi quello che hai trovato den", "." },
})
